-- Development/staging catalogue seed. Apply only after the Batch 0 category seed.
-- Names mirror Woodbay catalogue groupings; no technical specifications are invented.
insert into public.products (category_id, name, slug, short_description, status, is_featured, sort_order)
select c.id, p.name, p.slug, p.description, 'published', p.featured, p.sort_order
from (values
('pantry-solutions','Glass Pantry With Bidding','glass-pantry-with-bidding','Pantry Solutions',true,10),('pantry-solutions','Tall Pantry','tall-pantry','Pantry Solutions',false,20),('pullout-solutions','Bottle Pullout','bottle-pullout','Pullout Solutions',true,10),('corner-solutions','Corner Basket','corner-basket','Corner Solutions',true,10),('corner-solutions','Magic Corner','magic-corner','Corner Solutions',false,20),('cabinet-hinges','Soft Close Hinge','soft-close-hinge','Cabinet Hinges',true,10),('tandem-box','Tandem Box','tandem-box-system','Tandem Box',true,10),('aluminium-profiles','Aluminium Profile','aluminium-profile','Aluminium Profiles',false,10),('wardrobe-series','Wardrobe Trouser Rack','wardrobe-trouser-rack','Wardrobe Series',true,10),('wardrobe-series','Wardrobe Shoe Rack','wardrobe-shoe-rack','Wardrobe Series',false,20),('wardrobe-series','Wardrobe Lift','wardrobe-lift','Wardrobe Series',true,30),('smart-kitchen-waterfall-sinks','Waterfall Sink','waterfall-sink','Smart Kitchen / Waterfall Sinks',true,10),('wallpaper','Wallpaper','wallpaper','Home Decor',true,10),('charcoal-louvers','Charcoal Louvers','charcoal-louvers','Home Decor',true,20),('glass-mosaic-tiles','Glass Mosaic Tiles','glass-mosaic-tiles','Home Decor',false,30)
) as p(category_slug,name,slug,description,featured,sort_order) join public.product_categories c on c.slug=p.category_slug on conflict (slug) do nothing;
